// src/lib/payment-copy.ts
//
// The ONE place creator-facing payment copy states what the payment legally
// means. Three sends carried a literal bracketed "to be
// determined" placeholder while asserting a binding obligation on the creator
// at the moment money moved: the promo-materials email, the payout
// notification, and the Stripe Connect onboarding nudge.
//
// The rule, per the issue: say something TRUE.
//   - When the deal has a frozen contract (creator_offers.contract_text,
//     generated by generateOfferContract and delivered inline with the
//     acceptance email under CONTRACT_SEPARATOR), reference those terms and
//     the date they were sent.
//   - When it does not (no template configured — the production norm today),
//     assert NO binding obligation and do not promise anything further. The
//     copy used to say the terms "will follow by email", and nothing ever
//     sent them: terms ride only inside the agreement-confirmation email,
//     which has already gone out by this point. A promise nobody keeps is the
//     same defect as the bracketed placeholder this module was written to
//     remove, one politeness level up.
//
// Note the ordering fact the old copy got wrong: the contract is NOT "a
// separate email" or "an attachment" — when it exists, it was sent inline in
// the acceptance email. This module is pure and hermetically testable.

import { formatContractDate } from './contracts';

/**
 * The legal-meaning sentence for a payment-adjacent email.
 *
 * `contractGeneratedAt` must be the offer's contract_generated_at ONLY when
 * contract_text is actually frozen on the deal (callers gate on both columns);
 * anything unparseable is treated as "no contract", which fails toward the
 * weaker, safer claim.
 *
 * `deliverablesPhrase` is the caller's in-context noun phrase, e.g.
 * "the deliverables above" or "the agreed deliverables".
 */
export function agreementTermsSentence(
  contractGeneratedAt: string | null | undefined,
  deliverablesPhrase: string,
): string {
  const ms = contractGeneratedAt ? Date.parse(contractGeneratedAt) : NaN;
  if (Number.isFinite(ms)) {
    return (
      `Collecting this payment confirms you're in for ${deliverablesPhrase}, ` +
      `per the agreement terms sent with your acceptance email on ${formatContractDate(ms)}.`
    );
  }
  return 'The deliverables and amount above are the agreed terms for this collaboration.';
}

/**
 * Caller-side gate: the timestamp is only meaningful when the contract text
 * itself is frozen on the deal. Returns the value to hand to
 * agreementTermsSentence.
 */
export function contractSentAt(offer: {
  contract_text?: string | null;
  contract_generated_at?: string | null;
}): string | null {
  if (!offer.contract_text || offer.contract_text.trim().length === 0) return null;
  return offer.contract_generated_at ?? null;
}

// ── What happens next, after a creator says yes ─────────────────────────────
//
// The acceptance note (negotiation-tick.ts scheduleAcceptanceNote) told every
// creator, unconditionally:
//
//   "You'll get a quick payment-setup email from us next, and the promo pack
//    follows right after that."
//
// Four things are wrong with that, and they compound:
//
//   1. THE POOL CANNOT RECEIVE EMAIL. Most scraped creators have no contact
//      email. For them a "payment-setup email" is a
//      promise about a channel that does not exist for them. The payout
//      onboarding row is stamped channel:'email' with send_mode NULL, so it is
//      neither auto-sendable nor human-queueable for a DM creator: the tick
//      picks it up, fails to resolve a recipient, pushes send_after +120s, and
//      retries forever without ever writing a failure.
//   2. IT IS STRIPE-CONNECT-ONLY. The email is generated inside
//      `if (result.ok && result.needs_onboarding)` in execute-payment.ts. PayPal
//      and paper-money settle instantly and generate no such email at all.
//   3. "NEXT" IS WRONG. A human has to approve the payment authorization first.
//   4. THE ORDER IS INVERTED on the settled path: instant settlement flips to
//      paid and calls sendPromoMaterials immediately, so the promo pack arrives
//      and the payment-setup email never does.
//
// This is the exact defect class the top of this file was written to remove: a
// promise nobody keeps. So the replacement promises only the two things that are
// true on every branch — a human signs it off, and then the payment details and
// the pack come — and, for a creator we cannot email, it ASKS for the one piece
// of information that would make the money path work at all. That question is
// the only moment in the whole flow where asking for it is natural.

export interface NextStepInput {
  /** The surface this acceptance note itself is going out on. */
  channel: 'email' | 'dm';
  /**
   * True when we hold an address we could actually send payment setup to —
   * `creator_offers.payout_email` or `influencers.contact_email`. False for
   * most scraped creators.
   */
  emailReachable: boolean;
}

/**
 * The "what happens next" sentence for an acceptance note.
 *
 * No timeframe, deliberately. The approval step is a human and the send cadence
 * is randomised inside a window, so "quick" and "next" were both unbacked. A
 * creator is better served by a correct sequence with no clock than a clock
 * nobody is holding.
 */
export function nextStepSentence(input: NextStepInput): string {
  const signoff = 'Someone here signs this off first.';
  if (input.emailReachable) {
    return `${signoff} After that you'll get the payment details, then the promo pack. Nothing for you to do until then.`;
  }
  // No email on file. Do not promise an email, and get the address.
  return input.channel === 'dm'
    ? `${signoff} After that we'll come back to you right here with the payment details and the promo pack. If you'd rather handle the payment side by email, send me the address to use and I'll send it there.`
    : `${signoff} After that you'll get the payment details, then the promo pack. Reply with the best email for the payment side if this is not it.`;
}
